#include <iostream>

int main() {
    int x = 42;
    int* ptr = &x;        // ptr хранит адрес x в памяти
    std::cout << ptr;     // выведет адрес, например 0x7ffc1234
    std::cout << *ptr;    // 42 — разыменование, доступ к значению по адресу

    *ptr = 100;           // меняем значение x через указатель
    std::cout << x;       // 100 — x изменился!

    // Нулевой указатель (C++11, предпочтительнее NULL или 0)
    int* p1 = nullptr;    // указывает никуда
    if (!p1) std::cout << "Указатель пуст\n";

    // void* — указатель на любой тип, нуждается в приведении для разыменования
    void* vp = &x;
    int* ip = static_cast<int*>(vp);
}

int arr[5] = {10, 20, 30, 40, 50};
int* p = arr;           // p указывает на arr[0]

p + 1;      // адрес arr[1] (смещение на sizeof(int) байт)
p + 2;      // адрес arr[2]
*(p + 2);   // 30 — то же самое, что arr[2]

p++;        // теперь p указывает на arr[1]
++p;        // arr[2]
p += 2;     // arr[4]

// Разница между двумя указателями — количество элементов между ними
int* p2 = arr + 4;
std::cout << p2 - p;    // 4 (тип ptrdiff_t)

// Сравнение указателей
p < p2;     // true

int x = 10;
int& ref = x;       // ref — другое имя для x (алиас)
ref = 20;           // x становится 20

// Ссылка должна быть инициализирована при объявлении
// int& bad; // ОШИБКА: ссылка без инициализации

// const ссылка — может привязываться к временным значениям и литералам
const int& cref = 42;           // OK: продлевает время жизни временного
const int& cref2 = x + y;       // OK
// int& r = 42;                 // ОШИБКА: не-const ссылка не привязывается к временному (rvalue)

// Ссылки не могут быть null, не могут быть перепривязаны

int x = 10;
int&& rref = 42;        // привязывается к rvalue (временному значению)
int&& rref2 = std::move(x); // приведение lvalue к rvalue-ссылке

// std::move НЕ перемещает данные — он только кастует тип к rvalue-ссылке
// Это даёт понять компилятору: «я больше не буду использовать s1, можете забрать его данные»
std::string s1 = "hello";
std::string s2 = std::move(s1); // s1 теперь в "valid but unspecified state"
// s1 может быть пустой строкой, но деструктор вызовется безопасно

int add(int a, int b) { return a + b; }
int sub(int a, int b) { return a - b; }

int (*func_ptr)(int, int) = add;  // тип: указатель на функцию(int, int) -> int
func_ptr = sub;                   // можно переназначать на другую функцию

std::cout << func_ptr(5, 3);      // 2 — вызывает sub

