#include <iostream>

// Одиночный объект
int* p = new int(42);     // выделяет память, вызывает конструктор
std::cout << *p;          // 42
delete p;                 // вызывает деструктор, освобождает память
p = nullptr;              // хорошая практика после delete — защита от двойного удаления

// Массив
int* arr = new int[5]{1,2,3,4,5};
delete[] arr;             // ВАЖНО: delete[] для массивов, иначе UB!
arr = nullptr;

// Опасности:
// 1. Утечка памяти: забыли вызвать delete
// 2. Double delete: удалили один и тот же указатель дважды
// 3. Use after delete: обращение через висячий (dangling) указатель
// 4. Mismatch: new[] с delete или new с delete[] — неопределённое поведение

#include <memory>
#include <iostream>

class Resource {
public:
    Resource() { std::cout << "Ресурс получен\n"; }
    ~Resource() { std::cout << "Ресурс освобождён\n"; }
    void use() { std::cout << "Использование ресурса\n"; }
};

void demo() {
    // unique_ptr — единственное владение
    std::unique_ptr<Resource> u1 = std::make_unique<Resource>();
    u1->use();
    // std::unique_ptr<Resource> u2 = u1; // ОШИБКА: копирование запрещено
    std::unique_ptr<Resource> u2 = std::move(u1); // OK: передача владения
    // u1 теперь nullptr

    // shared_ptr — совместное владение через подсчёт ссылок
    std::shared_ptr<Resource> s1 = std::make_shared<Resource>();
    std::shared_ptr<Resource> s2 = s1; // копируется, счётчик = 2
    std::cout << s1.use_count(); // 2
    // Память освободится автоматически, когда умрёт последний shared_ptr

    // weak_ptr — слабая ссылка, не увеличивает счётчик
    std::weak_ptr<Resource> w = s1;
    if (auto locked = w.lock()) { locked->use(); } // проверяем, жив ли объект
}

// Правила:
// - По умолчанию используйте unique_ptr
// - shared_ptr когда нужно совместное владение
// - Никогда не делайте new/shared_ptr вручную — используйте make_unique/make_shared
// - Избегайте raw new/delete в современном C++

// Принцип: ресурс приобретается в конструкторе, освобождается в деструкторе
// Гарантирует: никаких утечек при исключениях, раннем return и т.д.

class FileHandle {
    FILE* f_;
public:
    FileHandle(const char* name) : f_(std::fopen(name, "r")) {
        if (!f_) throw std::runtime_error("Не удалось открыть файл");
    }
    ~FileHandle() { if (f_) std::fclose(f_); }
    // Запрет копирования — только один владелец
    FileHandle(const FileHandle&) = delete;
    FileHandle& operator=(const FileHandle&) = delete;
    // Move разрешен
    FileHandle(FileHandle&& other) noexcept : f_(other.f_) { other.f_ = nullptr; }
    FILE* get() const { return f_; }
};

void func() {
    FileHandle f("data.txt"); // при выходе из области видимости — автоматическое закрытие
    // даже если брошено исключение!
}

struct Counter {
    int count = 0;
    Counter& increment() {
        ++count;
        return *this; // возврат ссылки на себя для чейнинга
    }
    void print() const { std::cout << count; }
};

Counter c;
c.increment().increment().print(); // 2 — цепочка вызовов
